#!/usr/bin/env node
// SPDX-License-Identifier: CC0-1.0
//
// Regenerates test/fixtures/envelope-v2-vector.json: one asset and one metadata envelope v2, sealed for a
// throwaway ML-KEM-768 key under the context of the app's envelopeAAD vector.
//
// Every key, nonce and salt is derived from a public label, so the key can never protect anything real and the
// output is identical on every run. The test suite checks the committed file against a fresh run.
//
//   node test/fixtures/generate-envelope-v2-vector.js

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { ml_kem768 } = require('@noble/post-quantum/ml-kem.js');
const { sealEnvelope, forArweave } = require('../support/seal-envelope');
const { payloadFingerprint } = require('../../scripts/utils/shared-definitions');
const aadVector = require('./envelope-aad-vector.json');

const KEY_SEED_LABEL = 'INHERITOR CLI envelope v2 test vector: throwaway ML-KEM-768 key';
const derive = (label, length) => crypto.createHash('sha512').update(label).digest().subarray(0, length);

function buildVector() {
    const { publicKey, secretKey } = ml_kem768.keygen(derive(KEY_SEED_LABEL, 64));
    const context = {
        deploymentIdentity: aadVector.deploymentIdentity,
        inheritanceId: aadVector.inheritanceId,
        testator: aadVector.testator,
        beneficiary: aadVector.beneficiary
    };
    const randomness = (purpose) => ({
        contentKey: derive(`${purpose}: content key`, 32),
        payloadNonce: derive(`${purpose}: payload nonce`, 12),
        encapsulationSeed: derive(`${purpose}: ML-KEM encapsulation`, 32),
        salt: derive(`${purpose}: HKDF salt`, 32),
        wrapNonce: derive(`${purpose}: wrap nonce`, 12),
        xwingPlaceholder: derive(`${purpose}: X-Wing placeholder`, 48)
    });

    const assetPlaintext = 'Inheritor envelope v2 test asset. Throwaway key, never protects real data.';
    const asset = sealEnvelope({
        plaintext: Buffer.from(assetPlaintext, 'utf8'),
        context: { ...context, purpose: 'asset' },
        mlkemPublicKey: publicKey,
        randomness: randomness('asset'),
        fileType: 'txt'
    });
    const arweaveEnvelopeJson = JSON.stringify(forArweave(asset.envelope));

    const metadataPlaintext = JSON.stringify({ name: 'Test Testator', message: 'Throwaway test vector' });
    const metadata = sealEnvelope({
        plaintext: Buffer.from(metadataPlaintext, 'utf8'),
        context: { ...context, purpose: 'metadata' },
        mlkemPublicKey: publicKey,
        randomness: randomness('metadata'),
        fileType: 'json'
    });

    return {
        description: 'Envelope v2 vector for the recovery CLI, generated by generate-envelope-v2-vector.js with a throwaway ML-KEM-768 key derived from mlkemKeySeedLabel (sha512, first 64 bytes, ml_kem768.keygen). The context is the app\'s envelopeAAD vector. Not sealed by the app: it checks the CLI against the app\'s sealing steps as written in QSCryptionManager.swift.',
        mlkemKeySeedLabel: KEY_SEED_LABEL,
        mlkemPublicKeySha256: crypto.createHash('sha256').update(publicKey).digest('hex'),
        mlkemSecretKeySha256: crypto.createHash('sha256').update(secretKey).digest('hex'),
        context,
        asset: {
            plaintext: assetPlaintext,
            fileType: 'txt',
            arweaveEnvelopeJson,
            payloadFingerprint: payloadFingerprint(arweaveEnvelopeJson),
            releasedWrappedK: asset.wrappedK.toString('base64')
        },
        metadata: {
            plaintext: metadataPlaintext,
            testatorDataHex: Buffer.from(JSON.stringify(metadata.envelope), 'utf8').toString('hex')
        }
    };
}

/** The throwaway secret key, for tests. */
function vectorSecretKey() {
    return Buffer.from(ml_kem768.keygen(derive(KEY_SEED_LABEL, 64)).secretKey);
}

if (require.main === module) {
    fs.writeFileSync(path.join(__dirname, 'envelope-v2-vector.json'), JSON.stringify(buildVector(), null, 2) + '\n');
    console.log('wrote test/fixtures/envelope-v2-vector.json');
}

module.exports = { buildVector, vectorSecretKey };
